import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Spell variants and glyphs","description":"","frontmatter":{},"headers":[],"relativePath":"guide/magic/variants-and-glyphs.md","filePath":"guide/magic/variants-and-glyphs.md"}'),s={name:"guide/magic/variants-and-glyphs.md"};function r(o,e,l,d,p,g){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="spell-variants-and-glyphs" tabindex="-1">Spell variants and glyphs <a class="header-anchor" href="#spell-variants-and-glyphs" aria-label="Permalink to &quot;Spell variants and glyphs&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> <strong>Implementation:</strong> this redesign is not established as implemented. <strong>Availability:</strong> not established as live. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-09 against Batch 04.</p><p><a href="/Syrolands-Public/game-design/magic/variants-and-glyphs.html">Full design specification</a></p><p>Learned glyphs may change a known pattern&#39;s shape, delivery, targeting, effect or cost/stability. A tighter projectile, wider burst, lingering field or harder limb-focused cast are examples, not guaranteed spell options.</p><p>Every modifier needs a trade-off. Compatibility depends on the pattern, and a bounded complexity budget prevents unlimited stacking. Exact modifier counts and combinations remain undecided.</p><p>A modified variant may need its own memory complexity or extra reconstruction effort; memorizing Fireball does not settle how every Fireball variant works. Inscription could preserve useful variants in physical scrolls or books.</p><p>Visuals should explain the difference: Compression might look tighter, Persistence might leave a visible field. <a href="/Syrolands-Public/game-design/magic/presentation.html">Modular presentation</a> is a design goal, not an implemented renderer. <a href="/Syrolands-Public/guide/magic/memory-and-familiarity.html">Memory</a> · <a href="/Syrolands-Public/guide/professions/inscription.html">Inscription</a>.</p>',7)])])}const h=a(s,[["render",r]]);export{m as __pageData,h as default};
